#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> custos(3);
    for (int i = 0; i < 3; ++i) {
        cin >> custos[i];
    }

    sort(custos.begin(), custos.end());

    int ans = 0;
    for (int i = 0; i < 3; ++i) {
        if (n >= custos[i]) {
